package com.google.javascript.rhino.jstype;

import com.google.common.base.Preconditions;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.Iterables;
import com.google.common.collect.Lists;
import com.google.common.collect.Sets;
import com.google.javascript.rhino.ErrorReporter;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class FunctionType_setPrototype_TriageGen0Test {

    private FunctionType functionType;

    @Before
    public void setUp() {
        // We use a spy or mock because FunctionType has many internal dependencies
        functionType = mock(FunctionType.class, Mockito.CALLS_REAL_METHODS);
    }

    @Test
    public void testSetPrototype_NullArgument() {
        boolean result = functionType.setPrototype(null);
        assertFalse("Should return false when prototype is null", result);
    }

    @Test
    public void testSetPrototype_ConstructorSelfReference() {
        PrototypeObjectType prototype = mock(PrototypeObjectType.class);
        when(functionType.isConstructor()).thenReturn(true);
        when(functionType.getInstanceType()).thenReturn(prototype);

        boolean result = functionType.setPrototype(prototype);
        assertFalse("Should return false if prototype is the same as getInstanceType() for a constructor", result);
    }

    @Test
    public void testSetPrototype_OrdinaryFunction_Success() {
        PrototypeObjectType prototype = mock(PrototypeObjectType.class);
        when(functionType.isConstructor()).thenReturn(false);
        when(functionType.isInterface()).thenReturn(false);

        boolean result = functionType.setPrototype(prototype);

        assertTrue("Should return true for successful assignment", result);
        assertEquals("Prototype should be set", prototype, functionType.getPrototype());
        // Verify owner is set
        Mockito.verify(prototype).setOwnerFunction(functionType);
    }

    @Test
    public void testSetPrototype_Constructor_WithSuperClass() {
        PrototypeObjectType prototype = mock(PrototypeObjectType.class);
        FunctionType superClass = mock(FunctionType.class);

        when(functionType.isConstructor()).thenReturn(true);
        when(functionType.isInterface()).thenReturn(false);
        when(functionType.getSuperClassConstructor()).thenReturn(superClass);
        when(functionType.getInstanceType()).thenReturn(mock(ObjectType.class));

        boolean result = functionType.setPrototype(prototype);

        assertTrue(result);
        Mockito.verify(superClass).addSubType(functionType);
    }

    @Test
    public void testSetPrototype_Constructor_NoSuperClass() {
        PrototypeObjectType prototype = mock(PrototypeObjectType.class);

        when(functionType.isConstructor()).thenReturn(true);
        when(functionType.isInterface()).thenReturn(false);
        when(functionType.getSuperClassConstructor()).thenReturn(null);
        when(functionType.getInstanceType()).thenReturn(mock(ObjectType.class));

        boolean result = functionType.setPrototype(prototype);

        assertTrue(result);
    }

    @Test
    public void testSetPrototype_Interface_WithSuperClassAndExtendedInterfaces() {
        PrototypeObjectType prototype = mock(PrototypeObjectType.class);
        FunctionType superClass = mock(FunctionType.class);

        ObjectType extendedInterface = mock(ObjectType.class);
        FunctionType extendedInterfaceConstructor = mock(FunctionType.class);

        when(functionType.isConstructor()).thenReturn(false);
        when(functionType.isInterface()).thenReturn(true);
        when(functionType.getSuperClassConstructor()).thenReturn(superClass);
        when(functionType.getExtendedInterfaces()).thenReturn(Collections.singletonList(extendedInterface));
        when(extendedInterface.getConstructor()).thenReturn(extendedInterfaceConstructor);

        boolean result = functionType.setPrototype(prototype);

        assertTrue(result);
        Mockito.verify(superClass).addSubType(functionType);
        Mockito.verify(extendedInterfaceConstructor).addSubType(functionType);
    }

    @Test
    public void testSetPrototype_Interface_WithNoExtendedInterfaces() {
        PrototypeObjectType prototype = mock(PrototypeObjectType.class);
        FunctionType superClass = mock(FunctionType.class);

        when(functionType.isConstructor()).thenReturn(false);
        when(functionType.isInterface()).thenReturn(true);
        when(functionType.getSuperClassConstructor()).thenReturn(superClass);
        when(functionType.getExtendedInterfaces()).thenReturn(Collections.emptyList());

        boolean result = functionType.setPrototype(prototype);

        assertTrue(result);
        Mockito.verify(superClass).addSubType(functionType);
    }

    @Test
    public void testSetPrototype_Interface_ExtendedInterfaceHasNoConstructor() {
        PrototypeObjectType prototype = mock(PrototypeObjectType.class);
        FunctionType superClass = mock(FunctionType.class);

        ObjectType extendedInterface = mock(ObjectType.class);

        when(functionType.isConstructor()).thenReturn(false);
        when(functionType.isInterface()).thenReturn(true);
        when(functionType.getSuperClassConstructor()).thenReturn(superClass);
        when(functionType.getExtendedInterfaces()).thenReturn(Collections.singletonList(extendedInterface));
        when(extendedInterface.getConstructor()).thenReturn(null);

        boolean result = functionType.setPrototype(prototype);

        assertTrue(result);
        Mockito.verify(superClass).addSubType(functionType);
        // Verify no crash and no interaction with a non-existent constructor
    }
}
